class Person:
    def __init__(self, name, age):
        self.__name = name
        self.__age = age

    def get_name(self):
        return self.__name

    def get_age(self):
        return self.__age

    def is_age_valid(self):
        return self.__age > 0


def main():
    import sys

    lines = sys.stdin.read().strip().split('\n')
    idx = 0
    results = []

    while idx < len(lines):
        if idx + 1 >= len(lines):
            break
        name = lines[idx].strip()
        try:
            age = int(lines[idx + 1].strip())
        except:
            idx += 2
            continue

        person = Person(name, age)

        if person.is_age_valid():
            results.append(f"Name: {person.get_name()}")
            results.append(f"Age: {person.get_age()}")
        else:
            results.append("Invalid age")

        idx += 2

    for r in results:
        print(r)


if __name__ == "__main__":
    main()
